func:
// Ders 8'de ajanlarin yazdigi sartnamenin tarif ettigi raporu uretir.
//
// Gercek hayatta bu veri SAP'tan gelir (MARD.LABST, MARC.MINBE, MAKT).
// Burada onu temsil eden sabit bir liste var; amac Excel'in
// sozlesmesini ogrenmek, SAP baglantisi kurmak degil.

const BUGUN = new Date(msg.zaman || Date.now());

const ham = [
  { kod: "M-1001", tanim: "Rulman 6204-2RS", depo: "1000", stok: 0,  min: 20, sonSiparis: "2026-08-11" },
  { kod: "M-1002", tanim: "Conta NBR 40mm",  depo: "1000", stok: 8,  min: 15, sonSiparis: "2026-08-24" },
  { kod: "M-1003", tanim: "V-Kayis A-90",    depo: "1200", stok: 18, min: 15, sonSiparis: "2026-08-02" },
  { kod: "M-1004", tanim: "Hidrolik yag 20L",depo: "1200", stok: 3,  min: 12, sonSiparis: "2026-08-27" },
  { kod: "M-1005", tanim: "Filtre elemani",  depo: "1000", stok: 62, min: 30, sonSiparis: "2026-07-19" }
];
// M-1005 bilerek bol stoklu: 62 > 30 x 1,5 = 45. Rapora GIRMEMELI.
// Filtrenin calistigini gormenin en kolay yolu, elenmesi gereken
// bir satiri veriye koymaktir.

// Sartnamedeki uc seviye:
//   KRITIK  stok = 0
//   UYARI   stok < min
//   IZLE    stok < min * 1,5
const IZLE_CARPANI = 1.5;

function seviye(stok, min) {
  if (stok === 0) return "KRITIK";
  if (stok < min) return "UYARI";
  if (stok < min * IZLE_CARPANI) return "IZLE";
  return null;   // raporda yeri yok
}

// Stil anahtarlari xlsx-populate kutuphanesinden gelir.
// Arka plan "backgroundColor" DEGIL, "fill" adini tasir --
// yanlis anahtar verdiginizde dugum net soyluyor:
//   _Style.style: 'backgroundColor' is not a valid style
const RENK = {
  KRITIK: { yazi: "9C0006", zemin: "FFC7CE" },
  UYARI:  { yazi: "9C6500", zemin: "FFEB9C" },
  IZLE:   { yazi: "006100", zemin: "C6EFCE" }
};

const satirlar = [];
const sayac = { KRITIK: 0, UYARI: 0, IZLE: 0 };

ham.forEach((m, i) => {
  const s = seviye(m.stok, m.min);
  if (!s) return;
  sayac[s]++;

  // Excel satir numarasi: 1 baslik + o ana kadar eklenen satirlar
  const satirNo = satirlar.length + 2;

  satirlar.push({
    "Malzeme": m.kod,
    "Tanim": m.tanim,
    "Depo": m.depo,
    "Stok": m.stok,
    "Minimum": m.min,

    // FORMUL: parametresiz bir fonksiyon, Ingilizce formul metni dondurur.
    // Bu yuzden tabloyu bir function dugumunde kurmak zorundasiniz --
    // JSON bir fonksiyon tasiyamaz.
    "Fark": () => "=D" + satirNo + "-E" + satirNo,

    // Hucreye stil vermek icin duz deger yerine {value, style} nesnesi
    "Durum": {
      value: s,
      style: { bold: true, fontColor: RENK[s].yazi, fill: RENK[s].zemin }
    },

    "Son siparis": {
      value: new Date(m.sonSiparis),
      style: { numberFormat: "dd.MM.yyyy" }
    }
  });
});

msg.payload = {
  data: {
    "Kritik Stok": satirlar,
    "Ozet": [
      { "Olcut": "Rapor tarihi", "Deger": { value: BUGUN, style: { numberFormat: "dd.MM.yyyy HH:mm" } } },
      { "Olcut": "Taranan malzeme", "Deger": ham.length },
      { "Olcut": "KRITIK", "Deger": sayac.KRITIK },
      { "Olcut": "UYARI",  "Deger": sayac.UYARI },
      { "Olcut": "IZLE",   "Deger": sayac.IZLE }
    ]
  }
};

msg.ozet = sayac;
msg.satirSayisi = satirlar.length;

node.status({
  fill: sayac.KRITIK > 0 ? "red" : "yellow",
  shape: "dot",
  text: satirlar.length + " satir / " + sayac.KRITIK + " kritik"
});

return msg;

const g = new Date();
const iki = n => (n < 10 ? '0' : '') + n;
const damga = g.getFullYear() + iki(g.getMonth()+1) + iki(g.getDate());
msg.filename = '/internal-storage-files/rapor/' + 'kritik-stok-' + damga + '.xlsx';
return msg;

// Excel buffer'ini e-posta ekine cevirir.
//
// json-to-excel dugumu msg.payload'a bir Buffer birakir. MS Graph ise
// eki BASE64 metin olarak ister. Ders 9'da base64 formdan ICERI
// geliyordu; burada aynı bicim DISARI gidiyor.

const buf = msg.payload;

if (!Buffer.isBuffer(buf)) {
  node.error("Beklenen Excel buffer'i gelmedi, gelen tip: " + typeof buf, msg);
  return null;
}

const s = msg.ozet || { KRITIK: 0, UYARI: 0, IZLE: 0 };
const NL = String.fromCharCode(10);

// Dosya adina tarih koymak, gelen kutusunda ayni adli 30 dosya
// birikmesini onler.
const g = new Date();
const iki = n => (n < 10 ? "0" : "") + n;
const damga = g.getFullYear() + iki(g.getMonth() + 1) + iki(g.getDate());
const dosyaAdi = "kritik-stok-" + damga + ".xlsx";

const govde = [
  "<p>Gunluk kritik stok raporu ektedir.</p>",
  "<table cellpadding='6' style='border-collapse:collapse'>",
  "<tr><td style='background:#FFC7CE'><b>KRITIK</b></td><td><b>" + s.KRITIK + "</b></td></tr>",
  "<tr><td style='background:#FFEB9C'><b>UYARI</b></td><td><b>" + s.UYARI + "</b></td></tr>",
  "<tr><td style='background:#C6EFCE'><b>IZLE</b></td><td><b>" + s.IZLE + "</b></td></tr>",
  "</table>",
  "<p style='color:#888;font-size:12px'>Bu ileti aXet.flows tarafindan otomatik uretildi.</p>"
].join(NL);

msg.payload = {
  subject: "Kritik stok raporu -- " + iki(g.getDate()) + "." + iki(g.getMonth() + 1) + "." + g.getFullYear(),

  // Alicilar koda GOMULU DEGIL: secret dugumu msg.alicilar'i dolduruyor.
  // Ders 8'in sartnamesi de "e-posta listesi konfigurasyondan okunacak,
  // koda gomulmeyecek" diyordu -- burada onu uyguluyoruz.
  // secret tek bir metin tasidigi icin virgulle ayrilmis liste kabul ediyoruz.
  toRecipients: String(msg.alicilar || "")
    .split(",")
    .map(a => a.trim())
    .filter(Boolean)
    .map(a => ({ emailAddress: { address: a } })),

  // KRITIK varsa e-posta yuksek onemle gitsin
  importance: s.KRITIK > 0 ? "high" : "normal",

  body: { contentType: "html", content: govde },

  attachments: [{
    "@odata.type": "#microsoft.graph.fileAttachment",
    name: dosyaAdi,
    contentType: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
    contentBytes: buf.toString("base64")
  }]
};

node.status({
  fill: "blue", shape: "dot",
  text: dosyaAdi + " / " + Math.round(buf.length / 1024) + " KB"
});

return msg;

// Koşu kaydini SQL'e yazacak sorguyu hazirlar.
//
// sql-query dugumu sorguyu Mustache ile isler: '{{payload.x}}' yazarsaniz
// msg.payload.x degeriyle degistirir. Bu KOLAY ama TEHLIKELIDIR --
// parametre baglama degil, metin birlestirmedir. Kullanicidan gelen bir
// degeri dogrudan koyarsaniz SQL enjeksiyonuna acik olursunuz.
//
// Bu yuzden degerleri burada temizleyip msg.query'yi kendimiz kuruyoruz.

const s = msg.ozet || { KRITIK: 0, UYARI: 0, IZLE: 0 };

// Sayilari sayi oldugundan emin olarak gecirmek en ucuz savunma
const sayi = n => {
  const v = parseInt(n, 10);
  return Number.isFinite(v) ? v : 0;
};

// Metin icin: tek tirnaklari ikile ve uzunlugu sinirla
const metin = t => "'" + String(t || "").replace(/'/g, "''").slice(0, 200) + "'";

const g = new Date();
const iki = n => (n < 10 ? "0" : "") + n;
const tarih = g.getFullYear() + "-" + iki(g.getMonth() + 1) + "-" + iki(g.getDate())
            + " " + iki(g.getHours()) + ":" + iki(g.getMinutes());

msg.query = "INSERT INTO stok_kosu (tarih, kritik, uyari, izle, satir, kaynak) VALUES ("
  + metin(tarih) + ", "
  + sayi(s.KRITIK) + ", "
  + sayi(s.UYARI) + ", "
  + sayi(s.IZLE) + ", "
  + sayi(msg.satirSayisi) + ", "
  + metin(msg.kaynak || "elle")
  + ")";

node.status({ fill: "grey", shape: "dot", text: "kayit: " + tarih });
return msg;

const e = msg.error || {};
const s = e.source || {};
msg.payload = new Date().toISOString() + ' | ' + (s.name || s.type) + ' | ' + e.message;
msg.filename = '/internal-storage-files/rapor/' + 'hatalar.log';
node.status({ fill: 'red', shape: 'ring', text: e.message.slice(0, 40) });
return msg;
